function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(title,html){mentorDemo?.pause();assistanceDemo?.pause();stopMotion();$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;$('#dialog').showModal();applyLanguage()}
function closeModal(){$('#dialog').close()}
function linkSource(s){return `<a href="${esc(safeUrl(s.url||s.sourceUrl))}" target="_blank" rel="noopener noreferrer">${esc(txt(s)||s.url)} ↗</a>`}
function stepSourceIds(c,s){return Array.isArray(s.sourceIds)&&s.sourceIds.length?s.sourceIds:c.sourceIds||[]}
function sourceLinks(ids){return (ids||[]).map(id=>sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<div class="source">${linkSource(s)}<p>${esc(typeof s.scope==='object'?txt(s.scope):txt(s,'scope')||s.publisher||'')}</p></div>`).join('')}
function photoFor(c){return photos.find(p=>p.id===c.photoId)||photos.find(p=>p.courseIds?.includes(c.id))||null}
function photoCredit(p){return `${p.attribution||p.author} · ${p.license}`}
