function workflowRequirement(){const c=course(),s=allSteps(c)[activeStep],gate=gateState(c,s);if(gate.ready)return {ready:true,label:t(activeStep===allSteps(c).length-1?'finishCourse':'stepNext'),text:t('allRequirementsMet'),target:'#complete'};if(gate.assembled)return {label:t('answerCheck'),text:t('quizStillRequired'),target:'#quizSection'};const practice=practiceStatus(c,s),{result}=exerciseContext();if(!practice.ready){const narration=$('#mentorGuideText')?.textContent||'',status=$('#mentorGuideStatus')?.textContent||'';return {label:t(mentorGuide?.status==='waiting'?'nextNarration':mentorGuide?.status==='paused'?'demoPlay':'watchDemoNext'),text:[status,narration].filter(Boolean).join(' · ').slice(0,520)||t('watchFirst'),target:'#mentorAction'}};if(assistanceDemo?.status==='playing')return {label:t('guidanceRunning'),text:t('guidanceInProgress'),target:'#assistanceStatus'};if(assistanceDemo?.status==='paused')return {label:t('resumeGuidance'),text:t('guidancePaused'),target:'#assist'};if(practice.passed)return {label:t('submitEvidence'),text:t('evidenceReady'),target:'#place',submit:true};const text=[...practice.missing,!result.passed?exerciseText(result.readout):''].filter(Boolean).join(' · ');return {label:t(!practice.moved||!practice.released||!practice.position?'finishOperation':'finishTask'),text,target:!practice.moved||!practice.released||!practice.position?'#assist':'#exerciseTask'};}
function updateDockGuide(){const active=['preparing','speaking','waiting','paused'].includes(mentorGuide?.status);if($('#dockGuideControls'))$('#dockGuideControls').hidden=!active;if($('#dockSkipTour')){$('#dockSkipTour').hidden=!active||!!$('#mentorGuideSkipTour')?.disabled;$('#dockSkipTour').disabled=!!$('#mentorGuideSkipTour')?.disabled}if($('#dockPauseGuide'))$('#dockPauseGuide').textContent=t(mentorGuide?.status==='paused'?'demoPlay':'demoPause')}
function refreshWorkflow(translate=true){if(currentPage!=='workshop'||!$('#workflowAction'))return;const c=course(),s=allSteps(c)[activeStep],gate=gateState(c,s),next=workflowRequirement();if($('#demoGate'))$('#demoGate').textContent=`${demonstrationReady(c,s)?'✓':'○'} ${t('demoGate')} · ${t(demonstrationReady(c,s)?'passed':'pending')}`;$('#assemblyGate').textContent=`${gate.assembled?'✓':'○'} ${t('taskGate')} · ${t(gate.assembled?'passed':'pending')}`;$('#quizGate').textContent=`${gate.checked?'✓':'○'} ${t('quizGate')} · ${t(gate.checked?'passed':'pending')}`;$('#assemblyGate').dataset.passed=String(gate.assembled);$('#quizGate').dataset.passed=String(gate.checked);for(const id of ['#workflowAction','#complete'])if($(id)){$(id).textContent=(id==='#complete'?t('stepNext')+(mentorGuide?.status==='waiting'&&!gate.assembled?' · '+t('nextNarration'):''):next.label)+' →';$(id).setAttribute('aria-label',t('stepNext')+': '+next.label);$(id).disabled=false;$(id).dataset.ready=String(gate.ready);$(id).setAttribute('aria-describedby','nextRequirements')}if($('#nextRequirements'))$('#nextRequirements').textContent=next.label+' · '+next.text;$('#place').disabled=gate.assembled;$('#stepNext').disabled=activeStep>=unlocked(c)||activeStep>=allSteps(c).length-1;updateDockGuide();if(translate)applyLanguage()}
function advanceWorkflow(){const next=workflowRequirement();if(next.ready)return completeStep();if(next.submit)return confirmAssembly();if(next.target==='#mentorAction'){if(mentorGuide?.status==='waiting')mentorGuide.next();else if(['idle','stopped','complete'].includes(mentorGuide?.status)||mentorGuide?.status==='paused')mentorDemo.play();else toast(next.text);return false;}if(assistanceDemo?.status==='paused'){assistanceDemo.play();updateAssistanceUI()}focusSection(next.target);toast(next.text);return false;}

function focusSection(id){const el=$(id);el?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});el?.focus({preventScroll:true})}
const physicalControls=Object.freeze({ArrowUp:'y-',ArrowDown:'y+',ArrowLeft:'x-',ArrowRight:'x+',KeyW:'y-',KeyA:'x-',KeyS:'y+',KeyD:'x+',KeyI:'z+',PageUp:'z+',KeyK:'z-',PageDown:'z-',KeyJ:'r-',KeyQ:'r-',KeyL:'r+',KeyE:'r+'});
